import{_ as o,o as a,c,a2 as r}from"./chunks/framework.C0KMm31j.js";const t="/Nav2ArticlesSite/article-assets/2026-07-24/nav2_controller_source_01_boundary.png",l="/Nav2ArticlesSite/article-assets/2026-07-24/nav2_controller_source_02_lifecycle.png",d="/Nav2ArticlesSite/article-assets/2026-07-24/nav2_controller_source_03_loop.png",i="/Nav2ArticlesSite/article-assets/2026-07-24/nav2_controller_source_04_velocity.png",n="/Nav2ArticlesSite/article-assets/2026-07-24/nav2_controller_source_05_progress.png",s="/Nav2ArticlesSite/article-assets/2026-07-24/nav2_controller_source_06_goal.png",g=JSON.parse('{"title":"一条 Path，如何被 53 个函数炼成速度？逐函数拆解 Nav2 Controller Server","description":"全局规划器只给出一条 Path，机器人并不会因此自动运动。真正持续读取位姿、观察局部障碍、调用控制算法、检查进度并发布速度的，是 nav2controller。","frontmatter":{"title":"一条 Path，如何被 53 个函数炼成速度？逐函数拆解 Nav2 Controller Server","description":"全局规划器只给出一条 Path，机器人并不会因此自动运动。真正持续读取位姿、观察局部障碍、调用控制算法、检查进度并发布速度的，是 nav2controller。","date":"2026-07-24","topic":"Nav2 工程实践","section":"三 · 局部控制与速度生成","readingTime":11,"source":"2026-07-24/nav2_controller_source_walkthrough.md","status":"published","cover":"/article-assets/2026-07-24/nav2_controller_source_01_boundary.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-controller-source-walkthrough"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"一条 Path，如何被 53 个函数炼成速度？逐函数拆解 Nav2 Controller Server"}],["meta",{"property":"og:description","content":"全局规划器只给出一条 Path，机器人并不会因此自动运动。真正持续读取位姿、观察局部障碍、调用控制算法、检查进度并发布速度的，是 nav2controller。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-controller-source-walkthrough"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-24/nav2_controller_source_01_boundary.png"}],["meta",{"property":"article:published_time","content":"2026-07-24"}],["meta",{"name":"twitter:title","content":"一条 Path，如何被 53 个函数炼成速度？逐函数拆解 Nav2 Controller Server"}],["meta",{"name":"twitter:description","content":"全局规划器只给出一条 Path，机器人并不会因此自动运动。真正持续读取位姿、观察局部障碍、调用控制算法、检查进度并发布速度的，是 nav2controller。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-24/nav2_controller_source_01_boundary.png"}]],"prev":{"text":"每 50 毫秒淘汰数百种走法：DWB 如何从速度窗口里选出机器人下一步？","link":"/nav2/nav2-dwb-core-algorithm"},"next":{"text":"不采样、不打分，一条公式如何让机器人优雅转弯？拆解 Nav2 Graceful Controller 核心算法","link":"/nav2/nav2-graceful-controller-core-algorithm"}},"headers":[],"relativePath":"nav2/nav2-controller-source-walkthrough.md","filePath":"nav2/nav2-controller-source-walkthrough.md","lastUpdated":null}'),h={name:"nav2/nav2-controller-source-walkthrough.md"};function p(u,e,_,m,b,P){return a(),c("div",null,[...e[0]||(e[0]=[r('<h1 id="一条-path-如何被-53-个函数炼成速度-逐函数拆解-nav2-controller-server" tabindex="-1">一条 Path，如何被 53 个函数炼成速度？逐函数拆解 Nav2 Controller Server <a class="header-anchor" href="#一条-path-如何被-53-个函数炼成速度-逐函数拆解-nav2-controller-server" aria-label="Permalink to &quot;一条 Path，如何被 53 个函数炼成速度？逐函数拆解 Nav2 Controller Server&quot;">​</a></h1><p>全局规划器只给出一条 <code>Path</code>，机器人并不会因此自动运动。真正持续读取位姿、观察局部障碍、调用控制算法、检查进度并发布速度的，是 <code>nav2_controller</code>。</p><p>本文以当前本地 <code>nav2_controller 1.1.20</code> 为实现基线，覆盖 53 个生产函数：<code>main()</code> 1 个，<code>ControllerServer</code> 21 个，两个 Progress Checker 共 12 个，三个 Goal Checker 共 19 个。测试函数和 pluginlib 注册宏不计入。</p><h2 id="一、本包是控制任务容器-不是某一种局部算法" tabindex="-1">一、本包是控制任务容器，不是某一种局部算法 <a class="header-anchor" href="#一、本包是控制任务容器-不是某一种局部算法" aria-label="Permalink to &quot;一、本包是控制任务容器，不是某一种局部算法&quot;">​</a></h2><h3 id="_1-1-输入、输出与包外边界" tabindex="-1">1.1 输入、输出与包外边界 <a class="header-anchor" href="#_1-1-输入、输出与包外边界" aria-label="Permalink to &quot;1.1 输入、输出与包外边界&quot;">​</a></h3><p><img src="'+t+'" alt="nav2_controller 包边界"></p><p>上游通过 <code>nav2_msgs/action/FollowPath</code> 提供 <code>Path</code>、<code>controller_id</code> 和 <code>goal_checker_id</code>。运行期输入还包括 Odometry 速度、TF 机器人位姿、Local Costmap 和 <code>SpeedLimit</code>。输出是 <code>cmd_vel</code>、Action Feedback，以及成功、失败或取消终态。</p><p>本包不实现 DWB、RPP、MPPI 或 TEB。真正计算速度的是包外 <code>nav2_core::Controller</code> 插件；Costmap、TF、OdomSubscriber、SimpleActionServer、Lifecycle Manager 和 Velocity Smoother 也不在本包内。本包负责把这些对象装进同一控制闭环，并提供两个 Progress Checker 与三个 Goal Checker。</p><h2 id="二、八个入口如何建立和销毁服务器" tabindex="-1">二、八个入口如何建立和销毁服务器 <a class="header-anchor" href="#二、八个入口如何建立和销毁服务器" aria-label="Permalink to &quot;二、八个入口如何建立和销毁服务器&quot;">​</a></h2><h3 id="_2-1-main-、controllerserver-与析构函数" tabindex="-1">2.1 <code>main()</code>、<code>ControllerServer()</code> 与析构函数 <a class="header-anchor" href="#_2-1-main-、controllerserver-与析构函数" aria-label="Permalink to &quot;2.1 `main()`、`ControllerServer()` 与析构函数&quot;">​</a></h3><p><img src="'+l+'" alt="Controller Server 生命周期"></p><p><code>main()</code> 接收进程参数，调用 rclcpp 与 Spdlog 初始化，创建 <code>ControllerServer</code>，把节点基础接口交给 <code>rclcpp::spin()</code>，退出时关闭 ROS 2 和日志。它没有控制算法，只负责独立进程入口；组件方式则由文件末尾的注册宏交给包外 class_loader。</p><p><code>ControllerServer()</code> 接收 <code>NodeOptions</code>，构造 Lifecycle 节点。它声明控制频率、三个 Odom 速度阈值、插件 ID、限速 Topic、失败容忍时间和是否发布零速度；同时建立 Progress Checker、Goal Checker、Controller 三个 pluginlib Loader，并创建名为 <code>local_costmap</code> 的 <code>Costmap2DROS</code> 对象。此时插件、订阅和 Action 尚未创建。</p><p><code>~ControllerServer()</code> 是兜底清理路径，重置 Progress Checker，清空 Goal Checker 和 Controller 容器，停止 Costmap 线程。正常 Lifecycle cleanup 已经释放资源时，这些操作仍然安全。</p><h3 id="_2-2-on-configure" tabindex="-1">2.2 <code>on_configure()</code> <a class="header-anchor" href="#_2-2-on-configure" aria-label="Permalink to &quot;2.2 `on_configure()`&quot;">​</a></h3><p>输入是 Lifecycle transition，输出是 <code>SUCCESS</code> 或 <code>FAILURE</code>。函数读取插件列表与 Server 参数，必要时声明默认插件类型，配置包外 Local Costmap 并创建独立 <code>NodeThread</code>。</p><p>它用 pluginlib 创建一个 Progress Checker、多个 Goal Checker 和多个 Controller。Checker 的 <code>initialize()</code> 获得父节点和插件名，Controller 的 <code>configure()</code> 额外获得 TF Buffer 与 Costmap 共享指针。任一 pluginlib 创建异常都会让 configure 失败。</p><p>配置成功后，它创建包外 <code>OdomSubscriber</code>、Lifecycle <code>cmd_vel</code> Publisher、<code>follow_path</code> SimpleActionServer 和 <code>SpeedLimit</code> Subscription。节点进入 inactive，资源存在但还不接任务。</p><h3 id="_2-3-on-activate-与-on-deactivate" tabindex="-1">2.3 <code>on_activate()</code> 与 <code>on_deactivate()</code> <a class="header-anchor" href="#_2-3-on-activate-与-on-deactivate" aria-label="Permalink to &quot;2.3 `on_activate()` 与 `on_deactivate()`&quot;">​</a></h3><p><code>on_activate()</code> 激活 Costmap、全部 Controller、速度 Publisher 和 Action Server，注册 Server 动态参数回调，再创建 bond。Progress Checker 与 Goal Checker 没有独立 activate 接口，它们在 initialize 后即可被服务器调用。</p><p><code>on_deactivate()</code> 反向停止 Action、Controller 和 Costmap，然后调用 <code>publishZeroVelocity()</code>，再关闭 Publisher、注销参数回调并销毁 bond。零速度发布发生在 Publisher 停用之前，但仍要求 Topic 存在订阅者。</p><h3 id="_2-4-on-cleanup-与-on-shutdown" tabindex="-1">2.4 <code>on_cleanup()</code> 与 <code>on_shutdown()</code> <a class="header-anchor" href="#_2-4-on-cleanup-与-on-shutdown" aria-label="Permalink to &quot;2.4 `on_cleanup()` 与 `on_shutdown()`&quot;">​</a></h3><p><code>on_cleanup()</code> 调用每个包外 Controller 的 <code>cleanup()</code>，清空 Controller 与 Goal Checker，清理 Costmap，并释放 Action、Odom、Costmap 线程、速度 Publisher 和限速 Subscription。当前实现没有显式 <code>reset()</code> Progress Checker，但后续重新 configure 会创建新实例。</p><p><code>on_shutdown()</code> 只记录日志并返回成功，不编排额外停车或资源释放；停车主要依赖 deactivate、Action 异常路径和析构兜底。</p><h2 id="三、四个函数如何接住-goal-和-path" tabindex="-1">三、四个函数如何接住 Goal 和 Path <a class="header-anchor" href="#三、四个函数如何接住-goal-和-path" aria-label="Permalink to &quot;三、四个函数如何接住 Goal 和 Path&quot;">​</a></h2><h3 id="_3-1-findcontrollerid-与-findgoalcheckerid" tabindex="-1">3.1 <code>findControllerId()</code> 与 <code>findGoalCheckerId()</code> <a class="header-anchor" href="#_3-1-findcontrollerid-与-findgoalcheckerid" aria-label="Permalink to &quot;3.1 `findControllerId()` 与 `findGoalCheckerId()`&quot;">​</a></h3><p>两个函数都输入 Action Goal 中的字符串 ID，并通过引用输出本次使用的实例 ID。请求命中容器时直接选中；只有一个插件且请求 ID 为空时，才回退到唯一实例并打印一次警告。</p><p>非法的非空 ID 不会因为“只加载一个插件”而自动回退，而是返回 false。<code>computeControl()</code> 随后终止 Action。这与当前 Planner Server 在单插件环境下对错误 ID 的回退策略不同。</p><h3 id="_3-2-setplannerpath" tabindex="-1">3.2 <code>setPlannerPath()</code> <a class="header-anchor" href="#_3-2-setplannerpath" aria-label="Permalink to &quot;3.2 `setPlannerPath()`&quot;">​</a></h3><p>输入是 <code>nav_msgs::msg::Path</code>。空 Path 抛出 <code>PlannerException</code>；非空 Path 调用包外当前 Controller 的 <code>setPlan()</code>，把末端 Pose 保存为 <code>end_pose_</code>，重置当前 Goal Checker，并复制到 <code>current_path_</code>。</p><p>该函数既建立 Controller 的跟踪输入，也建立 Goal Checker 的终点和 Feedback 的剩余路径基准。它不做 TF 变换，具体 Controller 如何把 Path 变到局部坐标系由插件自己决定。</p><h3 id="_3-3-computecontrol" tabindex="-1">3.3 <code>computeControl()</code> <a class="header-anchor" href="#_3-3-computecontrol" aria-label="Permalink to &quot;3.3 `computeControl()`&quot;">​</a></h3><p><img src="'+d+'" alt="FollowPath 控制循环"></p><p>这是 <code>follow_path</code> Action 的执行回调。函数入口用 <code>lock_guard</code> 持有 <code>dynamic_params_lock_</code>，锁会覆盖整个 Goal 生命周期。它读取当前 Goal，调用两个 ID 查找函数，再执行 <code>setPlannerPath()</code> 和 Progress Checker 的 <code>reset()</code>。</p><p>函数记录最近有效命令时间，并用 <code>rclcpp::WallRate(controller_frequency_)</code> 建立控制周期。循环检查 Action Server 是否 active、是否取消，再以 <code>100 Hz</code> 等待 Costmap current。这个等待没有超时，也没有循环内取消检查。</p><p>每周期调用 <code>updateGlobalPath()</code>、<code>computeAndPublishVelocity()</code> 与 <code>isGoalReached()</code>。控制频率错过时只告警并重置 Rate。捕获 <code>PlannerException</code> 或标准异常时发布零速度并终止 Action；正常到达后根据 <code>publish_zero_velocity_</code> 决定是否停车，再设置 Action 成功。</p><h3 id="_3-4-updateglobalpath" tabindex="-1">3.4 <code>updateGlobalPath()</code> <a class="header-anchor" href="#_3-4-updateglobalpath" aria-label="Permalink to &quot;3.4 `updateGlobalPath()`&quot;">​</a></h3><p>它是抢占处理函数。没有 pending Goal 时无副作用；存在抢占时调用包外 SimpleActionServer 的 <code>accept_pending_goal()</code>，重新验证 Controller 与 Goal Checker ID，再用新 Path 调用 <code>setPlannerPath()</code>。</p><p><code>setPlannerPath()</code> 会重置 Goal Checker，但 <code>updateGlobalPath()</code> 不会重置 Progress Checker。因此新 Path 继承旧任务的进度基准和计时，这是当前实现边界。</p><h2 id="四、一个控制周期怎样产生速度和-feedback" tabindex="-1">四、一个控制周期怎样产生速度和 Feedback <a class="header-anchor" href="#四、一个控制周期怎样产生速度和-feedback" aria-label="Permalink to &quot;四、一个控制周期怎样产生速度和 Feedback&quot;">​</a></h2><h3 id="_4-1-computeandpublishvelocity" tabindex="-1">4.1 <code>computeAndPublishVelocity()</code> <a class="header-anchor" href="#_4-1-computeandpublishvelocity" aria-label="Permalink to &quot;4.1 `computeAndPublishVelocity()`&quot;">​</a></h3><p><img src="'+i+'" alt="单周期速度数据流"></p><p>该函数没有显式输入参数，输入全部来自成员与包外对象。它取得机器人 Pose，检查是否持续前进，读取 Odom，调用 Controller 插件，然后发布 Feedback 和速度。</p><p>包外 Controller 的 <code>computeVelocityCommands()</code> 接收当前 Pose、阈值化速度和当前 Goal Checker 指针，返回 <code>TwistStamped</code>。成功时更新 <code>last_valid_cmd_time_</code>。插件抛出 <code>PlannerException</code> 时，<code>failure_tolerance_</code> 为正值或 <code>-1.0</code> 会暂时构造零速度；正值超时后重新抛错，<code>-1.0</code> 则可以无限容忍。</p><p>Feedback 的 <code>speed</code> 是本周期命令的平面线速度模长，不是 Odom 实测速度。<code>distance_to_goal</code> 先搜索当前 Pose 最近的 Path 索引，再由包外几何工具累计剩余路径长度，因此也不是到终点的直线距离。</p><h3 id="_4-2-getrobotpose" tabindex="-1">4.2 <code>getRobotPose()</code> <a class="header-anchor" href="#_4-2-getrobotpose" aria-label="Permalink to &quot;4.2 `getRobotPose()`&quot;">​</a></h3><p>输入是待写入的 <code>PoseStamped</code> 引用。函数调用包外 <code>Costmap2DROS::getRobotPose()</code>；失败返回 false，成功复制当前 Pose 并返回 true。它不直接操作 TF Listener，但 Costmap 内部使用自己的 TF Buffer 完成坐标获取。</p><h3 id="_4-3-getthresholdedvelocity-与-getthresholdedtwist" tabindex="-1">4.3 <code>getThresholdedVelocity()</code> 与 <code>getThresholdedTwist()</code> <a class="header-anchor" href="#_4-3-getthresholdedvelocity-与-getthresholdedtwist" aria-label="Permalink to &quot;4.3 `getThresholdedVelocity()` 与 `getThresholdedTwist()`&quot;">​</a></h3><p>两个函数定义在头文件中。<code>getThresholdedVelocity()</code> 输入一个速度分量和阈值，绝对值大于阈值时保留原值，否则输出零。</p><p><code>getThresholdedTwist()</code> 输入 <code>nav_2d_msgs::msg::Twist2D</code>，分别用 X、Y、Theta 阈值调用前一个函数，输出滤除微小噪声的 Twist。这个结果同时传给 Controller 与 Goal Checker，阈值过大可能让真实低速被视为静止。</p><h3 id="_4-4-publishvelocity-与-publishzerovelocity" tabindex="-1">4.4 <code>publishVelocity()</code> 与 <code>publishZeroVelocity()</code> <a class="header-anchor" href="#_4-4-publishvelocity-与-publishzerovelocity" aria-label="Permalink to &quot;4.4 `publishVelocity()` 与 `publishZeroVelocity()`&quot;">​</a></h3><p><code>publishVelocity()</code> 输入 <code>TwistStamped</code>，只取其中 Twist，转换为 <code>geometry_msgs::msg::Twist</code>。只有 Lifecycle Publisher active 且至少有一个订阅者时才真正发布 <code>cmd_vel</code>。</p><p><code>publishZeroVelocity()</code> 没有输入，构造六个分量全为零的 <code>TwistStamped</code>，填写 Base Frame 和当前时间，再复用 <code>publishVelocity()</code>。它被取消、异常、deactivate 和可选成功停车路径调用。</p><h3 id="_4-5-isgoalreached" tabindex="-1">4.5 <code>isGoalReached()</code> <a class="header-anchor" href="#_4-5-isgoalreached" aria-label="Permalink to &quot;4.5 `isGoalReached()`&quot;">​</a></h3><p>函数先通过 <code>getRobotPose()</code> 获取当前 Pose，再读取并阈值化 Odom 速度。它用包外 <code>nav_2d_utils::transformPose()</code> 把 <code>end_pose_</code> 变到 Costmap Global Frame，最后调用当前 Goal Checker 的 <code>isGoalReached(current, goal, velocity)</code>。</p><p>输出是 bool。false 让控制循环继续；true 让 <code>computeControl()</code> 退出循环。Goal Checker 决定的是任务完成条件，不计算速度。</p><h2 id="五、两个回调怎样改变运行中的-controller" tabindex="-1">五、两个回调怎样改变运行中的 Controller <a class="header-anchor" href="#五、两个回调怎样改变运行中的-controller" aria-label="Permalink to &quot;五、两个回调怎样改变运行中的 Controller&quot;">​</a></h2><h3 id="_5-1-speedlimitcallback" tabindex="-1">5.1 <code>speedLimitCallback()</code> <a class="header-anchor" href="#_5-1-speedlimitcallback" aria-label="Permalink to &quot;5.1 `speedLimitCallback()`&quot;">​</a></h3><p>这是 <code>nav2_msgs::msg::SpeedLimit</code> Topic 回调。输入包含数值与“百分比还是绝对值”标志。函数遍历全部 Controller，调用包外 <code>setSpeedLimit()</code>，不只更新当前实例。</p><p>Server 本身不裁剪 <code>cmd_vel</code>，各 Controller 插件负责解释和执行限速。没有实现限速语义的插件，其行为取决于插件自身。</p><h3 id="_5-2-dynamicparameterscallback" tabindex="-1">5.2 <code>dynamicParametersCallback()</code> <a class="header-anchor" href="#_5-2-dynamicparameterscallback" aria-label="Permalink to &quot;5.2 `dynamicParametersCallback()`&quot;">​</a></h3><p>输入是候选 Parameter vector，输出 <code>SetParametersResult</code>。名称含点号的参数被跳过，让插件自己的动态回调处理。Server 参数则对 <code>dynamic_params_lock_</code> 执行 <code>try_lock()</code>；由于 <code>computeControl()</code> 整个任务期间持锁，FollowPath 正在执行时会返回失败。</p><p>成功获得锁后，它可更新 <code>controller_frequency</code>、三个 Odom 阈值和 <code>failure_tolerance</code>。每处理一个非插件参数就解锁一次，因此批量参数不是成员级事务；<code>controller_frequency</code> 也只会影响下一次创建 WallRate 的任务。<code>publish_zero_velocity</code> 和 <code>speed_limit_topic</code> 当前不在动态分支中。</p><h2 id="六、simpleprogresschecker-的七个函数" tabindex="-1">六、SimpleProgressChecker 的七个函数 <a class="header-anchor" href="#六、simpleprogresschecker-的七个函数" aria-label="Permalink to &quot;六、SimpleProgressChecker 的七个函数&quot;">​</a></h2><h3 id="_6-1-初始化、检查与基准状态" tabindex="-1">6.1 初始化、检查与基准状态 <a class="header-anchor" href="#_6-1-初始化、检查与基准状态" aria-label="Permalink to &quot;6.1 初始化、检查与基准状态&quot;">​</a></h3><p><img src="'+n+'" alt="Progress Checker 函数关系"></p><p><code>initialize()</code> 输入父 Lifecycle 节点弱指针和插件名，取得 Clock，声明并读取 <code>required_movement_radius</code> 与 <code>movement_time_allowance</code>，注册插件动态参数回调。输出通过成员状态体现。</p><p><code>check()</code> 输入当前 <code>PoseStamped</code>，用包外 <code>poseToPose2D()</code> 转换。没有基准或移动足够时调用 <code>resetBaselinePose()</code> 并返回 true；否则比较当前时间与允许时间，未超时返回 true，超时返回 false。</p><p><code>reset()</code> 只把 <code>baseline_pose_set_</code> 置为 false，下一次检查会重建基准。<code>resetBaselinePose()</code> 保存 Pose、当前时间和有效标志。</p><h3 id="_6-2-距离判断与参数回调" tabindex="-1">6.2 距离判断与参数回调 <a class="header-anchor" href="#_6-2-距离判断与参数回调" aria-label="Permalink to &quot;6.2 距离判断与参数回调&quot;">​</a></h3><p><code>isRobotMovedEnough()</code> 输入当前 Pose2D，把它与基准 Pose 交给 <code>pose_distance()</code>，距离严格大于半径才算有进展。<code>pose_distance()</code> 计算 XY 差并用 <code>std::hypot()</code> 输出欧氏距离。</p><p><code>dynamicParametersCallback()</code> 接收 Parameter vector，热更新移动半径和允许时间，始终返回成功。它没有独立互斥锁，与 <code>check()</code> 并发时的成员读写由当前执行模型承担。</p><h2 id="七、poseprogresschecker-的五个函数" tabindex="-1">七、PoseProgressChecker 的五个函数 <a class="header-anchor" href="#七、poseprogresschecker-的五个函数" aria-label="Permalink to &quot;七、PoseProgressChecker 的五个函数&quot;">​</a></h2><h3 id="_7-1-在平移之外承认旋转进度" tabindex="-1">7.1 在平移之外承认旋转进度 <a class="header-anchor" href="#_7-1-在平移之外承认旋转进度" aria-label="Permalink to &quot;7.1 在平移之外承认旋转进度&quot;">​</a></h3><p><code>initialize()</code> 先调用父类初始化，继承距离、时间和父类动态回调，再声明角度阈值并注册自己的回调。由于父类和子类各保存一个回调句柄，两组参数都能处理。</p><p><code>check()</code> 与父类流程相同，但显式调用本类 <code>isRobotMovedEnough()</code>。该函数只要父类 <code>pose_distance()</code> 超过半径，或 <code>poseAngleDistance()</code> 超过角度阈值，就返回 true。</p><p><code>poseAngleDistance()</code> 输入两个 Pose2D，用包外 <code>angles::shortest_angular_distance()</code> 计算最短角差并取绝对值。<code>dynamicParametersCallback()</code> 只处理 <code>required_movement_angle</code>，并返回成功。</p><h2 id="八、三个-goal-checker-的十九个函数" tabindex="-1">八、三个 Goal Checker 的十九个函数 <a class="header-anchor" href="#八、三个-goal-checker-的十九个函数" aria-label="Permalink to &quot;八、三个 Goal Checker 的十九个函数&quot;">​</a></h2><h3 id="_8-1-simplegoalchecker-的六个函数" tabindex="-1">8.1 SimpleGoalChecker 的六个函数 <a class="header-anchor" href="#_8-1-simplegoalchecker-的六个函数" aria-label="Permalink to &quot;8.1 SimpleGoalChecker 的六个函数&quot;">​</a></h3><p><img src="'+s+'" alt="Goal Checker 函数关系"></p><p><code>SimpleGoalChecker()</code> 设置 XY、Yaw 容差、stateful、对称朝向和平方容差默认值。<code>initialize()</code> 声明并读取这些参数，缓存 XY 容差平方并注册动态回调。<code>reset()</code> 让 <code>check_xy_</code> 恢复 true。</p><p><code>isGoalReached()</code> 输入当前 Pose、目标 Pose 和速度，但本类不使用速度。它先比较 XY 平方距离；<code>stateful=true</code> 时，XY 一旦达标就不再复查。随后用包外 TF 和 angles 工具检查 Yaw；对称模式还接受目标朝向加 180°。</p><p><code>getTolerances()</code> 输出位置与朝向容差，速度字段写入无效哨兵。参数回调更新 XY、Yaw、stateful 与对称朝向，并在 XY 改变时同步平方缓存。</p><h3 id="_8-2-stoppedgoalchecker-的五个函数" tabindex="-1">8.2 StoppedGoalChecker 的五个函数 <a class="header-anchor" href="#_8-2-stoppedgoalchecker-的五个函数" aria-label="Permalink to &quot;8.2 StoppedGoalChecker 的五个函数&quot;">​</a></h3><p><code>StoppedGoalChecker()</code> 在父类默认值上增加平移和旋转停稳阈值。<code>initialize()</code> 先调用父类初始化，再声明停稳参数并注册派生类回调，因此父类几何参数和本类速度参数都可热更新。</p><p><code>isGoalReached()</code> 输入当前 Pose、目标 Pose 与 Odom Twist。父类几何判定失败就返回 false；通过后，角速度绝对值与平面线速度模长还必须分别低于阈值。</p><p><code>getTolerances()</code> 先取得父类 Pose 容差，再覆盖线速度与角速度容差。参数回调更新两个停稳阈值。</p><h3 id="_8-3-positiongoalchecker-的八个函数" tabindex="-1">8.3 PositionGoalChecker 的八个函数 <a class="header-anchor" href="#_8-3-positiongoalchecker-的八个函数" aria-label="Permalink to &quot;8.3 PositionGoalChecker 的八个函数&quot;">​</a></h3><p><code>PositionGoalChecker()</code> 设置 XY 容差、平方缓存、stateful 和位置锁存默认值；<code>~PositionGoalChecker()</code> 是默认析构函数，不增加资源操作。<code>initialize()</code> 声明 XY 与 stateful 参数，读取初值、更新平方缓存并注册回调。<code>reset()</code> 清除 <code>position_reached_</code>。</p><p><code>isGoalReached()</code> 忽略速度与目标朝向，只计算 XY 平方距离。stateful 模式下，一旦位置达标，后续调用直接返回 true。<code>getTolerances()</code> 输出 XY 容差，把不参与判断的字段设置为无效值或单位四元数。</p><p><code>setXYGoalTolerance()</code> 是直接 C++ 接口，同时更新容差和平方缓存。参数回调完成同样更新，并可切换 stateful。</p><h2 id="九、从故障现象反推责任边界" tabindex="-1">九、从故障现象反推责任边界 <a class="header-anchor" href="#九、从故障现象反推责任边界" aria-label="Permalink to &quot;九、从故障现象反推责任边界&quot;">​</a></h2><h3 id="_9-1-控制闭环的分层判断" tabindex="-1">9.1 控制闭环的分层判断 <a class="header-anchor" href="#_9-1-控制闭环的分层判断" aria-label="Permalink to &quot;9.1 控制闭环的分层判断&quot;">​</a></h3><p>Action 拒绝先检查 Controller ID、Goal Checker ID 与空 Path；没有速度再检查 Lifecycle active、Costmap current、TF、Odom、Progress Checker 和包外 Controller 异常；到点不停或提前成功则检查 Goal Checker、Odom 阈值与 stateful；速度发布后机器人不动则继续查 Velocity Smoother、Topic remap 和底盘驱动。</p><p>这 53 个函数的核心价值不是实现某一种控制公式，而是把路径执行的状态、数据和插件边界固定下来。只有先判断故障属于 Server、Checker、Controller 插件还是速度下游，调参和源码修改才不会找错层。</p>',95)])])}const v=o(h,[["render",p]]);export{g as __pageData,v as default};
